+            ts_ms: 1,
+            seq: 0,
+            body: EventBody::RunStart(Box::new(RunStart {
+                format: FORMAT.into(),
+                version: VERSION,
+                run_id: "r1".into(),
+                participant: "m1".into(),
+                role: Role::Source,
+                attempt: 1,
+                host: String::new(),
+                build: String::new(),
+                run: info(),
